def _cstack(left, right):
    # ... 省略前置维度计算与 cleft 构造 ...
    cright = np.zeros((tot_outp, tot_inp), dtype=bool)
    if isinstance(right, Model):
        cright[-right.n_outputs:, -right.n_inputs:] = _coord_matrix(right, 'right', right.n_outputs)
    else:
        # 旧实现错误地填入了常数 1，丢掉了子模型已计算好的内部依赖矩阵结构：
        # cright[-right.shape[0]:, -right.shape[1]:] = 1
        # 修复后保留已计算的布尔依赖矩阵 right：
        cright[-right.shape[0]:, -right.shape[1]:] = right
    return np.hstack([cleft, cright])
